import * as X from './expansion.mjs';
import {MOVIES,REGULARS} from './data.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,extra='',disabled=false)=>`<button data-action="${action}" ${extra} ${disabled?'disabled':''}>${label}</button>`;
export function trainingCard(e){const level=e.training?.level||0,xp=e.xp||0;return `<div class="training"><h4>${e.training?X.SKILLS[e.training.skill].title+' · Level '+level:'Choose a specialty'}</h4><p class="note">${xp} completed jobs · ${level>=3?'Fully trained':`${(level+1)*8} jobs needed for next level · $${25+level*20} training · +$0.50/hr raise`}</p>${Object.entries(X.SKILLS).filter(([id])=>!e.training||e.training.skill===id).map(([id,k])=>button('xp-train',level?`Promote ${k.title}`:k.title,`data-id="${e.id}" data-kind="${id}"`,level>=3||xp<(level+1)*8)).join('')}<p class="note">${e.training?X.SKILLS[e.training.skill].desc:'Specialists work faster in their specialty or Help everywhere. Promotions improve morale.'}</p></div>`;}
export function renderNeighborhood(s,section,cover){const x=X.ensure(s);let h=`<div class="section-head"><div><h2>A store full of stories.</h2><p>Optional discoveries, familiar faces, and things worth saving for.</p></div></div><nav class="neighborhood-tabs" aria-label="Neighborhood activities">${[['stories','Neighbors'],['nights','Movie nights'],['collections','Rare tapes'],['visitor','Visitor'],['milestones','Milestones']].map(([id,label])=>button('xp-section',label,`data-kind="${id}" aria-pressed="${section===id}"`)).join('')}</nav>`;
 if(section==='stories')h+=`<p class="note">Serve each regular 1, 3, then 6 times to hear the next chapter. Staff checkouts count too. Each chapter earns $10; the final chapter adds a keepsake.</p><div class="crew-grid">${REGULARS.map((r,i)=>{const st=x.stories[i];return `<article class="staff-card"><span class="pill">${st.chapter===3?'STORY COMPLETE':`CHAPTER ${st.chapter+1} OF 3`}</span><h3>${esc(r.name)} · ${esc(X.STORIES[i][0])}</h3><p>“${esc(X.storyLine(s,i))}”</p><p class="note">${st.visits} visits served${st.chapter<3?` · Next chapter at ${[1,3,6][st.chapter]}`:` · ${esc(X.STORIES[i][5])}`}</p>${button('xp-story',st.chapter===3?'Keepsake earned':X.readyStory(s,i)?'Hear what happened · +$10':'Keep making movie night',`data-id="${i}"`,!X.readyStory(s,i))}</article>`;}).join('')}</div><h3>Your keepsake shelf</h3><p class="note">${x.keepsakes.length?x.keepsakes.map(esc).join(' · '):'Thank-you notes and souvenirs will appear here—and in your store.'}</p>`;
 if(section==='nights'){const current=x.night;h+=`<p class="note">Available from day 3, before opening. One event per shift. Extra visitors arrive midshift; themed rentals count all night. Missing the goal only costs the advertised setup fee.</p>${current?`<div class="brief"><h3>${esc(X.NIGHTS.find(n=>n.id===current.id)?.title)}</h3><p>${current.count}/${current.target} themed rentals · ${current.settled?'Finished':'Booked for today'}</p></div>`:''}<div class="upgrade-grid">${X.NIGHTS.map(n=>`<article class="upgrade-card"><h3>${n.title}</h3><p>${n.genre} night · $${n.cost} setup · ${n.target-(x.milestones.includes('screening')?1:0)} rentals for a $${n.reward} bonus.</p><p class="note">${s.stock.reduce((a,st,i)=>a+(MOVIES[i].genre===n.genre?st.ready:0),0)} matching tapes ready. Consider your crew and snack stock before booking.</p>${button('xp-night',s.day<3?'Unlocks day 3':s.phase!=='planning'?'Book before opening':current?'An event is already booked':`Host · $${n.cost}`,`data-kind="${n.id}"`,s.day<3||s.phase!=='planning'||!!current||s.cash<n.cost)}</article>`).join('')}</div><h3>Past movie nights · ${x.hosted} successful</h3>${x.nightHistory.map(n=>`<p class="note">Day ${n.day}: ${esc(n.title)} · ${n.count}/${n.target} · ${n.won?'A hit!':'Try again another day'}</p>`).join('')}`;}
 if(section==='collections')h+=`<p class="note">Collectors visit on even-numbered days from day 4. Every $18 purchase includes the exact edition shown, a rentable copy, and a permanent collection entry. Complete a set for a wall poster and $15.</p>${X.SETS.map(set=>`<h3>${set.title} ${x.sets.includes(set.id)?'· Poster earned ✓':''}</h3><div class="rare-grid">${X.RARES.filter(r=>r.set===set.id).map(r=>`<article class="movie-card ${x.rares.includes(r.id)?'rare-owned':''}">${cover(MOVIES[r.movie])}<div class="movie-info"><h3>${esc(r.title)}</h3><span class="pill">${x.rares.includes(r.id)?'COLLECTED ✓':'WATCH FOR THE COLLECTOR'}</span></div></article>`).join('')}</div>`).join('')}`;
 if(section==='visitor'){const g=x.guest;h+=`<p class="note">Visitors start on day 3. They arrive during the shift and stay until closing. Participation is optional.</p>`;if(!g)h+='<div class="empty-state"><h3>A friendly knock at the door…</h3><p>Keep the store open. Someone interesting may stop by.</p></div>';else if(g.resolved)h+='<div class="brief"><h3>Thanks for stopping by.</h3><p>Today’s visit is finished. A different opportunity arrives on another day.</p></div>';else if(s.phase!=='open')h+='<p class="note">That visit has ended. Open a new shift to meet another guest.</p>';else if(g.type==='collector'){const r=X.RARES.find(r=>r.id===g.rare);h+=`<div class="visitor-card">${cover(MOVIES[r.movie])}<div><h3>Milo’s trunk of tapes</h3><p>“Found this under a very opinionated cat. The sleeve survived.”</p><h4>${esc(r.title)}</h4><p>$18 · one rentable copy · collector’s edition for your album.</p>${button('xp-guest','Buy this edition · $18','data-kind="buy"',s.cash<18)} ${button('xp-guest','Not today','data-kind="decline"')}</div></div>`;}else if(g.type==='actor')h+=`<div class="brief"><h3>Rex Rewind, star of several almost-hits</h3><p>“You carry The Mummy Owes Me Twenty Bucks? I played the twenty bucks. Long story.”</p><p>Welcome Rex for a signed headshot, +2 goodwill and an $8 late-fee payment.</p>${button('xp-guest','Welcome Rex','data-kind="welcome"')} ${button('xp-guest','Maybe another time','data-kind="decline"')}</div>`;else h+=`<div class="brief"><h3>Penny Frames · neighborhood critic</h3><p>“I review the experience, not the carpet. Unless the carpet is extraordinary.”</p><p>${g.accepted?`${g.progress}/3 checkouts observed. The review arrives at closing.`:'Accept, then complete three checkouts before closing for $25 and a review keepsake. Staff checkouts count. No penalty if unfinished.'}</p>${button('xp-guest',g.accepted?'Review in progress':'Invite her to review','data-kind="accept"',g.accepted)} ${button('xp-guest','Pass on this visit','data-kind="decline"')}</div>`;}
 if(section==='milestones')h+=`<p class="note">${s.totalRentals} lifetime rentals. Each improvement appears in the room once installed. Drag the room to see the annex on the left.</p><div class="upgrade-grid">${X.MILESTONES.map(m=>`<article class="upgrade-card"><h3>${m.title}</h3><p>${m.desc}</p><p class="note">${Math.min(s.totalRentals,m.rentals)}/${m.rentals} rentals · ${m.cost?'$'+m.cost:'Free earned reward'}</p>${button('xp-milestone',x.milestones.includes(m.id)?'Installed ✓':s.totalRentals<m.rentals?'Keep growing':m.cost?`Install · $${m.cost}`:'Claim your reward',`data-kind="${m.id}"`,x.milestones.includes(m.id)||s.totalRentals<m.rentals||s.cash<m.cost)}</article>`).join('')}</div>`;
 return h;}
export function drawRewards(scene,s){const x=X.ensure(s),c=scene.ctx;
 if(x.milestones.includes('picks')){scene.round(700,100,120,66,2,'#48323b','#d5b175');scene.text('STAFF PICKS',760,113,8,'#ffe0a1','monospace');[0,6,10].forEach((id,i)=>scene.drawPoster(id,708+i*37,119,28,40));}
 x.sets.forEach((id,i)=>{const set=X.SETS.find(v=>v.id===id);scene.drawPoster(set.poster,875+i*60,195+i*30,44,60);});
 if(x.keepsakes.length){scene.round(390,195,85,9,1,'#b38a60');for(let i=0;i<Math.min(7,x.keepsakes.length);i++){c.fillStyle=['#f1cb76','#c3d1b2','#dd9bb1'][i%3];c.fillRect(395+i*10,180-(i%2)*4,7,15);}}
 if(x.milestones.includes('snackcounter')){scene.box(5.9,8,2,.6,.9,'#b48154','#805439','#c29764');for(let i=0;i<10;i++){const p=scene.p(6+i*.18,8.65,.9);c.fillStyle=i%2?'#f1c86c':'#d68183';c.fillRect(p.x,p.y-14,7,14);}}
 if(x.milestones.includes('screening')){scene.round(550,260,110,65,2,'#3b303e','#cbbca3');scene.round(556,266,98,51,1,'#b6d3d0');scene.text('COMING SOON',605,293,10,'#343955','monospace');scene.box(3.7,4,1.6,.5,.4,'#b37c88','#6d465f','#8a5c73');}
 if(x.milestones.includes('annex')){scene.path([{x:150,y:550},{x:260,y:495},{x:410,y:570},{x:300,y:630}],'#584251','#c49b72');scene.path([{x:150,y:550},{x:260,y:495},{x:260,y:425},{x:150,y:480}],'#74524f','#af8365');scene.path([{x:260,y:495},{x:410,y:570},{x:410,y:500},{x:260,y:425}],'#806052','#b58b65');for(let i=0;i<8;i++){scene.line(270+i*18,432+i*9,270+i*18,494+i*9,'#62473e',2);}for(let i=0;i<5;i++){scene.line(165+i*22,487-i*11,165+i*22,542-i*11,'#533a3b',2);}scene.text('COLLECTOR’S ANNEX',278,517,10,'#ffe0a1','monospace');scene.round(222,546,126,33,1,'#3b303b','#bc956a');for(let i=0;i<6;i++){c.fillStyle=['#bb6c83','#8bb6a5','#d4aa68'][i%3];c.fillRect(229+i*19,549,13,24);c.fillStyle='#e2d1aa';c.fillRect(231+i*19,554,9,3);}for(let i=0;i<3;i++)scene.drawPoster(i,285+i*33,456+i*16,24,36);}

 if(x.guest&&!x.guest.resolved&&s.phase==='open'){scene.person(2,8.3,{color:x.guest.type==='critic'?'#cf8cb6':x.guest.type==='actor'?'#d7b15c':'#73a5a1',skin:'#d7ac88',hair:'#59424c'},0,false);}
}
